	@Test
	void addAndRemoveKeepSnapshotIsolationAcrossRevisions() throws Exception {
		commitQuads(new long[][] { add(S1, P1, O1, 0, true) });
		long r0 = tripleStore.getDataRevision();
		assertThat(store.buildNowForTest()).isTrue();

		commitQuads(new long[][] { add(S1, P1, O2, G1, true) });
		awaitApplier();
		long r1 = tripleStore.getDataRevision();

		try (LmdbAdjacencyReadView oldView = store.acquire(r0); LmdbAdjacencyReadView newView = store.acquire(r1)) {
			assertThat(oldView.isExact()).isTrue();
			assertThat(newView.isExact()).isTrue();
			assertThat(probe(oldView, S1, P1, -1, -1, true)).hasSize(1);
			assertThat(probe(newView, S1, P1, -1, -1, true)).hasSize(2);
		}

		commitQuads(new long[][] { remove(S1, P1, O1, 0, true) });
		awaitApplier();
		long r2 = tripleStore.getDataRevision();
		try (LmdbAdjacencyReadView midView = store.acquire(r1); LmdbAdjacencyReadView newView = store.acquire(r2)) {
			assertThat(probe(midView, S1, P1, -1, -1, true)).hasSize(2);
			List<long[]> rows = probe(newView, S1, P1, -1, -1, true);
			assertThat(rows).hasSize(1);
			assertThat(rows.get(0)[2]).isEqualTo(O2);
			// incoming direction reflects the same commit
			assertThat(probe(newView, -1, P1, O1, -1, true)).isEmpty();
			assertThat(probe(midView, -1, P1, O1, -1, true)).hasSize(1);
		}
	}

	@Test
	void pendingWindowFallsBackOnlyForTouchedRows() throws Exception {
		commitQuads(new long[][] { add(S1, P1, O1, 0, true), add(S2, P1, O1, 0, true) });
		assertThat(store.buildNowForTest()).isTrue();

		store.pauseApplierForTest(true);
		try {
			commitQuads(new long[][] { add(S1, P1, O2, 0, true) });
			long r1 = tripleStore.getDataRevision();
			try (LmdbAdjacencyReadView view = store.acquire(r1)) {
				assertThat(view.isExact()).isTrue();
				// the touched row falls back (pending proof)
				long pendingBefore = store.snapshotMetrics().fallbacks(FallbackReason.PENDING_ROW);
				assertDeclined(view, S1, P1, -1, -1, true);
				assertThat(store.snapshotMetrics().fallbacks(FallbackReason.PENDING_ROW))
						.isGreaterThan(pendingBefore);
				// the incoming row of the same commit is also pending
				assertDeclined(view, -1, P1, O2, -1, true);
				// an untouched row keeps serving from the older version
				assertThat(probe(view, S2, P1, -1, -1, true)).hasSize(1);
				// A touched unbound-predicate row falls back before the first result.
				assertDeclined(view, S1, -1, -1, -1, true);
				// Paged CSF deliberately has no node-to-all-predicates locator, including for untouched rows.
				long enumerationBefore = store.snapshotMetrics()
						.fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE);
				assertDeclined(view, S2, -1, -1, -1, true);
				assertThat(store.snapshotMetrics().fallbacks(FallbackReason.PREDICATE_ENUMERATION_INCOMPLETE))
						.isGreaterThan(enumerationBefore);
			}
		} finally {
			store.pauseApplierForTest(false);
		}
		long r1 = tripleStore.getDataRevision();
		try (LmdbAdjacencyReadView view = store.acquire(r1)) {
			assertThat(probe(view, S1, P1, -1, -1, true)).hasSize(2);
		}
	}

